<?php
/**
 * Manages robots.txt crawler rules
 *
 * @link       https://techbysh.com
 * @since      1.0.0
 *
 * @package    Tavc
 * @subpackage Tavc/includes
 */

// If this file is called directly, abort.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Manages robots.txt crawler rules.
 *
 * Filters the robots.txt output to append blocks for selected AI crawlers
 * while preserving existing rules generated by other plugins or settings.
 *
 * @since      1.0.0
 * @package    Tavc
 * @subpackage Tavc/includes
 * @author     Techbysh
 */
class TAVC_Bot_Manager {

	/**
	 * Append disallow rules for selected AI bots to robots.txt output.
	 *
	 * @since    1.0.0
	 * @param    string    $output    The robots.txt content.
	 * @param    bool      $public    Whether the site is public.
	 * @return   string               The modified robots.txt content.
	 */
	public function add_robots_txt_rules( $output, $public ) {
		// If the site is not public, WordPress blocks all bots by default.
		// However, we still append selected blocks for completeness.
		$rules = $this->build_rules();

		if ( '' !== $rules ) {
			$output .= "\n# " . __( 'AI Visibility Control Rules', 'tbsh-ai-visibility-control' ) . "\n" . $rules;
		}

		return $output;
	}

	/**
	 * Build every rule this plugin adds to robots.txt.
	 *
	 * @since    1.3.0
	 * @return   string    Rules text, or an empty string when nothing is configured.
	 */
	public function build_rules() {
		$rules = $this->build_crawler_rules();

		/**
		 * Filters the Disallow rules generated for blocked AI crawlers.
		 *
		 * @since 1.0.0
		 *
		 * @param string $rules Rules text, one "User-agent / Disallow: /" group per blocked crawler.
		 */
		$filtered_rules = apply_filters( 'tavc_custom_robots_rules', $rules );
		if ( is_string( $filtered_rules ) ) {
			$rules = $filtered_rules;
		}

		$rules .= $this->build_custom_rules();
		$rules .= $this->build_content_signal_rules();

		return $rules;
	}

	/**
	 * "Disallow: /" groups for the crawlers blocked on the AI Crawlers tab.
	 *
	 * @since    1.3.0
	 * @return   string
	 */
	private function build_crawler_rules() {
		$blocked_bots = get_option( 'tavc_blocked_bots', array() );
		if ( empty( $blocked_bots ) || ! is_array( $blocked_bots ) ) {
			return '';
		}

		$rules = '';

		foreach ( TAVC_Bots::get_definitions() as $slug => $bot ) {
			if ( ! empty( $blocked_bots[ $slug ] ) ) {
				$rules .= "\n";
				$rules .= 'User-agent: ' . $bot['name'] . "\n";
				$rules .= "Disallow: /\n";
			}
		}

		return $rules;
	}

	/**
	 * Groups entered in the Custom robots.txt Rules editor.
	 *
	 * @since    1.3.0
	 * @return   string
	 */
	private function build_custom_rules() {
		$rules = '';

		foreach ( TAVC_Settings::get_custom_robots_rules() as $group ) {
			$rules .= "\n";
			foreach ( $group['agents'] as $agent ) {
				$rules .= 'User-agent: ' . $agent . "\n";
			}
			foreach ( $group['paths'] as $path ) {
				$rules .= 'Disallow: ' . $path . "\n";
			}
		}

		return $rules;
	}

	/**
	 * Content-Signal line for all crawlers.
	 *
	 * An empty "Disallow:" keeps the group valid without adding an Allow rule,
	 * so it can never override WordPress's own rules, even on non-public sites.
	 *
	 * @since    1.3.0
	 * @return   string
	 */
	private function build_content_signal_rules() {
		$values      = TAVC_Settings::get_content_signals();
		$definitions = TAVC_Settings::get_content_signal_definitions();
		$parts       = array();

		foreach ( $definitions as $key => $definition ) {
			if ( '' !== $values[ $key ] ) {
				$parts[] = $definition['token'] . '=' . $values[ $key ];
			}
		}

		if ( empty( $parts ) ) {
			return '';
		}

		return "\nUser-agent: *\nContent-Signal: " . implode( ', ', $parts ) . "\nDisallow:\n";
	}

	/**
	 * Web server rules that refuse the blocked crawlers before WordPress (or a
	 * page cache) runs. Shown on the AI Crawlers tab for copying; never written
	 * to any file by the plugin.
	 *
	 * Crawlers without their own user agent (Google-Extended, Applebot-Extended)
	 * are robots.txt tokens only and are left out. robots.txt and llms.txt stay
	 * readable so crawlers can still see the rules.
	 *
	 * @since    1.4.0
	 * @param    string    $format    'apache' or 'nginx'.
	 * @return   string               Rules, or '' when no blocked crawler has a user agent.
	 */
	public static function get_server_rules( $format ) {
		$definitions = TAVC_Bots::get_definitions();
		$agents      = array();

		foreach ( TAVC_Bots::get_blocked_settings() as $slug => $blocked ) {
			if ( $blocked && isset( $definitions[ $slug ] ) && '' !== $definitions[ $slug ]['ua'] ) {
				// Tokens are limited to letters, digits, "-", "_" and ".", so only the dot needs escaping.
				$agents[] = str_replace( '.', '\.', preg_replace( '/[^A-Za-z0-9._\-]/', '', $definitions[ $slug ]['ua'] ) );
			}
		}

		$agents = array_values( array_unique( array_filter( $agents ) ) );
		if ( empty( $agents ) ) {
			return '';
		}

		$pattern   = '(' . implode( '|', $agents ) . ')';
		$home_path = wp_parse_url( home_url( '/' ), PHP_URL_PATH );
		$home_path = is_string( $home_path ) ? trailingslashit( $home_path ) : '/';
		$exempt    = '^(/robots\.txt|' . preg_quote( $home_path, '/' ) . 'llms\.txt)$';

		if ( 'nginx' === $format ) {
			return "# AI Visibility Control: refuse blocked AI crawlers. Add inside the server { } block.\n"
				. "set \$tavc_block 0;\n"
				. "if (\$http_user_agent ~* \"{$pattern}\") { set \$tavc_block 1; }\n"
				. "if (\$uri ~ \"{$exempt}\") { set \$tavc_block 0; }\n"
				. "if (\$tavc_block = 1) { return 403; }\n";
		}

		return "# BEGIN AI Visibility Control: refuse blocked AI crawlers\n"
			. "<IfModule mod_rewrite.c>\n"
			. "RewriteEngine On\n"
			. "RewriteCond %{REQUEST_URI} !{$exempt}\n"
			. "RewriteCond %{HTTP_USER_AGENT} {$pattern} [NC]\n"
			. "RewriteRule .* - [F,L]\n"
			. "</IfModule>\n"
			. "# END AI Visibility Control\n";
	}
}
